recent.prompt:
Complete this browser task end to end, then report the result.

Buatkan HALAMAN (Page, bukan Postingan) baru di blog Blogger "KabarViral" (kabarviralterkiniterbaru.blogspot.com, akun khususstokyunobi@gmail.com sudah sign-in; jika diminta login pakai kredensial tersimpan; jika 2FA muncul: STOP dan laporkan angkanya).

LANGKAH:
1. Di blogger.com pilih blog KabarViral → menu "Halaman"/Pages → "Halaman baru"/New page.
2. Judul: YT Dashboard.
3. Pindah editor ke tampilan HTML (ikon pensil → HTML), HAPUS semua isi default, lalu tempel SELURUH kode HTML di bawah ini persis apa adanya (jangan diubah, jangan dipotong).
4. Klik Publikasikan/Publish.
5. JANGAN tambahkan halaman ini ke menu navigasi blog jika ditanya.
6. Laporkan URL halaman yang terbit (format .../p/yt-dashboard.html).

KODE HTML (tempel semuanya):
<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no">
<meta name="theme-color" content="#0f0f0f">
<title>YT Dashboard</title>
<style>
*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}
body{background:#0f0f0f;color:#f1f1f1;font-family:Roboto,system-ui,sans-serif;font-size:14px;min-height:100vh;padding-bottom:70px}
header{position:sticky;top:0;z-index:10;background:#0f0f0f;padding:12px 16px;border-bottom:1px solid #272727;display:flex;align-items:center;gap:10px}
header h1{font-size:17px;font-weight:700}
header .dot{width:10px;height:10px;border-radius:50%;background:#3ea6ff}
header .upd{font-size:10px;color:#606060;margin-left:2px}
#logout{margin-left:auto;background:none;border:1px solid #3d3d3d;color:#aaa;border-radius:20px;padding:6px 12px;font-size:12px}
nav{position:fixed;bottom:0;left:0;right:0;background:#0f0f0f;border-top:1px solid #272727;display:flex;z-index:10}
nav button{flex:1;background:none;border:none;color:#909090;padding:12px;font-size:13px;font-weight:500}
nav button.on{color:#fff;border-top:2px solid #f00}
.badge{min-width:20px;height:20px;border-radius:10px;background:#f00;color:#fff;font-size:11px;display:inline-flex;align-items:center;justify-content:center;padding:0 6px;margin-left:4px}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:12px}
.card{background:#1c1c1c;border-radius:12px;overflow:hidden;cursor:pointer}
.card .ch{display:flex;align-items:center;gap:10px;padding:10px}
.card img.ch{width:44px;height:44px;border-radius:50%;object-fit:cover;padding:0}
.card .nm{font-weight:600;font-size:13px;line-height:1.25}
.card .hd{color:#909090;font-size:11px}
.stats{display:flex;border-top:1px solid #2a2a2a}
.stats div{flex:1;text-align:center;padding:8px 4px}
.stats b{display:block;font-size:14px}
.stats span{font-size:10px;color:#909090}
.vrow{display:flex;gap:10px;padding:10px 12px;border-bottom:1px solid #1f1f1f;align-items:center}
.vrow img{width:120px;height:68px;border-radius:8px;object-fit:cover;flex-shrink:0;background:#222}
.vrow .t{font-size:13px;font-weight:500;line-height:1.3;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.vrow .m{font-size:11px;color:#909090;margin-top:4px}
.st{display:inline-block;font-size:10px;font-weight:700;border-radius:4px;padding:2px 6px;margin-top:4px}
.st.public{background:#1a3a1a;color:#6f6}
.st.private{background:#3a1a1a;color:#f88}
.st.unlisted{background:#3a3016;color:#fc6}
.st.scheduled{background:#16283a;color:#6cf}
.back{background:none;border:none;color:#3ea6ff;font-size:14px;padding:12px 16px}
.pubbtn{background:#c00;color:#fff;border:none;border-radius:8px;padding:8px 14px;font-weight:700;font-size:13px;margin-top:6px}
.pubbtn:disabled{background:#555}
#login{max-width:340px;margin:60px auto;padding:20px;text-align:center}
#login input{width:100%;padding:12px;border-radius:8px;border:1px solid #3d3d3d;background:#1c1c1c;color:#fff;font-size:15px;margin:10px 0}
#login button{width:100%;padding:12px;border:none;border-radius:8px;background:#c00;color:#fff;font-size:15px;font-weight:700}
.err{color:#f88;font-size:13px;margin-top:8px;min-height:18px}
.loading{text-align:center;color:#909090;padding:30px}
.empty{text-align:center;color:#909090;padding:40px 20px}
#confirm{position:fixed;inset:0;background:rgba(0,0,0,.7);display:none;align-items:center;justify-content:center;z-index:50;padding:20px}
#confirm .box{background:#1c1c1c;border-radius:12px;padding:20px;max-width:320px;width:100%}
#confirm .box p{margin-bottom:16px;line-height:1.4}
#confirm .row{display:flex;gap:10px}
#confirm .row button{flex:1;padding:12px;border-radius:8px;border:none;font-weight:700;font-size:14px}
#confirmYes{background:#c00;color:#fff}#confirmNo{background:#333;color:#fff}
.sec{padding:12px 16px 4px;color:#909090;font-size:12px;font-weight:600}
.hidden{display:none!important}
</style>
</head>
<body>
<header><span class="dot"></span><h1>YT Dashboard</h1><span class="upd" id="updAt"></span><button id="logout" class="hidden">Keluar</button></header>
<div id="login">
<h2 style="margin-bottom:6px">🔐 Masuk</h2>
<p style="color:#909090;font-size:13px">Masukkan password dashboard</p>
<input type="password" id="pw" placeholder="Password" autocomplete="current-password">
<button onclick="doLogin()">Masuk</button>
<div class="err" id="loginErr"></div>
</div>
<div id="main" class="hidden">
<div id="tab-channel"><div class="sec" id="chCount"></div><div class="grid" id="chGrid"></div></div>
<div id="tab-review" class="hidden"><div class="sec" id="pendCount"></div><div id="pendList"></div></div>
<div id="tab-videos" class="hidden"><button class="back" onclick="showTab('channel')">← Kembali</button><div class="sec" id="vidTitle"></div><div id="vidList"></div></div>
<div id="tab-revenue" class="hidden"><div class="sec" id="revPeriod"></div>
<div class="card" style="margin:12px;cursor:default"><div class="ch" style="display:block;padding:14px">
<div class="hd">Total estimasi 28 hari</div><div class="nm" style="font-size:22px" id="revTotal">…</div><div class="hd" id="revTotalUsd"></div>
</div></div><div id="revList"></div>
<div class="sec" style="font-weight:400">Angka estimasi YouTube (delay ~2 hari). Data diperbarui berkala dari server.</div>
</div></div>
<nav id="tabs" class="hidden">
<button id="tbCh" class="on" onclick="showTab('channel')">📺 Channel</button>
<button id="tbRv" onclick="showTab('review')">⏳ Review<span class="badge hidden" id="pendBadge"></span></button>
<button id="tbRp" onclick="showTab('revenue')">💰 Duit</button>
</nav>
<div id="confirm"><div class="box">
<p id="confirmText"></p>
<div class="row"><button id="confirmNo">Batal</button><button id="confirmYes">Publish</button></div>
</div></div>
<script>
//<![CDATA[
const FB_DB="https://yt-dashboard-yunobi-default-rtdb.asia-southeast1.firebasedatabase.app", FB_AUTH="zszMpcV3wzsoDXSc9xZZBBwIvM755gBQPPILlyhN";
let STATE=null, PWREC=null, CREATE_MODE=false;
async function fb(path,method,body){
let r=await fetch(FB_DB+"/yt/"+path+".json?auth="+FB_AUTH,{method:method||"GET",headers:{"Content-Type":"application/json"},body:body===undefined?undefined:JSON.stringify(body)});
if(!r.ok)throw new Error("fb "+r.status);return r.json();}
async function sha256hex(s){let b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(s));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("");}
function enterApp(){try{localStorage.setItem("ytd","1");}catch(e){}
document.getElementById("login").classList.add("hidden");document.getElementById("main").classList.remove("hidden");document.getElementById("tabs").classList.remove("hidden");document.getElementById("logout").classList.remove("hidden");loadState();}
async function doLogin(){let pw=document.getElementById("pw").value;
if(CREATE_MODE){if(pw.length<4){document.getElementById("loginErr").textContent="Minimal 4 karakter";return;}
let salt=[...crypto.getRandomValues(new Uint8Array(8))].map(x=>x.toString(16).padStart(2,"0")).join("");
let h=await sha256hex(salt+pw);
try{await fb("pw","PUT",{salt:salt,hash:h});enterApp();}catch(e){document.getElementById("loginErr").textContent="Gagal menyimpan, coba lagi";}return;}
if(!PWREC){document.getElementById("loginErr").textContent="Memuat…";return;}
let h=await sha256hex(PWREC.salt+pw);
if(h===PWREC.hash){enterApp();}else{document.getElementById("loginErr").textContent="Password salah";}}
async function initLogin(){try{PWREC=await fb("pw","GET");}catch(e){PWREC=null;}
if(!PWREC){CREATE_MODE=true;document.querySelector("#login p").textContent="Belum ada password — buat password baru:";document.querySelector("#login button").textContent="Buat & Masuk";}
try{if(localStorage.getItem("ytd")==="1"&&PWREC){enterApp();return;}}catch(e){}}
initLogin();
document.getElementById("pw").addEventListener("keydown",e=>{if(e.key==="Enter")doLogin();});
document.getElementById("logout").onclick=()=>{try{localStorage.removeItem("ytd");}catch(e){}location.reload();};
function showTab(t){["channel","review","videos","revenue"].forEach(x=>document.getElementById("tab-"+x).classList.add("hidden"));
document.getElementById("tab-"+t).classList.remove("hidden");
document.getElementById("tbCh").classList.toggle("on",t==="channel"||t==="videos");
document.getElementById("tbRv").classList.toggle("on",t==="review");
document.getElementById("tbRp").classList.toggle("on",t==="revenue");
if(t==="review")renderPending();if(t==="revenue")renderRevenue();}
function fmtRp(n){return "Rp "+Number(n||0).toLocaleString("id-ID");}
function renderRevenue(){let d=(STATE&&STATE.revenue)||{};
document.getElementById("revPeriod").textContent="Periode "+(d.period||"—");
document.getElementById("revTotal").textContent=fmtRp(d.total_idr);
document.getElementById("revTotalUsd").textContent="≈ US$ "+Number(d.total_usd||0).toLocaleString("en-US",{minimumFractionDigits:2});
let chs=((d.channels)||[]).slice().sort((a,b)=>(b.usd||0)-(a.usd||0));
document.getElementById("revList").innerHTML=chs.length?chs.map(c=>c.error?'<div class="vrow"><div><div class="t">'+c.handle+'</div><div class="m">gagal dimuat</div></div></div>':'<div class="vrow"><div style="flex:1"><div class="t">'+c.handle+'</div><div class="m">'+(c.monetized?"✅ Monetisasi":"⏳ Belum monetisasi")+'</div></div><div style="text-align:right"><div class="t">'+fmtRp(c.idr)+'</div><div class="m">US$ '+Number(c.usd||0).toLocaleString("en-US",{minimumFractionDigits:2})+'</div></div></div>').join(""):'<div class="empty">Belum ada data</div>';}
function renderChannels(){let d=(STATE&&STATE.channels)||[];
document.getElementById("chCount").textContent=d.length+" channel";
document.getElementById("chGrid").innerHTML=d.map(c=>c.error?'<div class="card"><div class="ch"><div><div class="nm">'+c.handle+'</div><div class="hd">error</div></div></div></div>':'<div class="card" onclick="openCh(\''+c.slug+"','"+(c.name||"").replace(/'/g,"")+'\')"><div class="ch"><img class="ch" src="'+c.thumb+'" loading="lazy" onerror="this.style.display=\'none\'"><div><div class="nm">'+c.name+'</div><div class="hd">'+c.handle+(c.mine?"":" • baca saja")+'</div></div></div><div class="stats"><div><b>'+c.subs_fmt+'</b><span>Subs</span></div><div><b>'+c.views_fmt+'</b><span>Views</span></div><div><b>'+c.videos+'</b><span>Video</span></div></div></div>').join("");}
async function openCh(slug,name){showTab("videos");document.getElementById("vidTitle").textContent=name;
let l=document.getElementById("vidList");l.innerHTML='<div class="loading">Memuat video…</div>';
let vids=(STATE&&STATE.videos&&STATE.videos[slug])||null;let vts=(STATE&&STATE.videos_ts&&STATE.videos_ts[slug])||0;
if(!vids||!vts){try{await fb("req_videos/"+slug,"PUT",Date.now());}catch(e){}
let tries=0;while(tries<30){await new Promise(r=>setTimeout(r,3000));tries++;
try{let s=await fb("state","GET");if(s&&s.videos&&s.videos[slug]&&(s.videos_ts||{})[slug]>vts){STATE=s;vids=s.videos[slug];break;}}catch(e){}}}
l.innerHTML=vids&&vids.length?vids.map(v=>vrow(v,slug)).join(""):'<div class="empty">Belum ada video / coba lagi sebentar</div>';}
function stLabel(v){if(v.privacy==="public")return '<span class="st public">PUBLIK</span>';
if(v.privacy==="scheduled")return '<span class="st scheduled">TERJADWAL '+(v.scheduled_at||"")+"</span>";
if(v.privacy==="unlisted")return '<span class="st unlisted">UNLISTED</span>';
return '<span class="st private">PRIVATE</span>';}
function vrow(v,slug,review){return '<div class="vrow"><img src="'+v.thumb+'" loading="lazy" onerror="this.style.display=\'none\'">'
+'<div><div class="t">'+v.title+'</div><div class="m">👁 '+v.views_fmt+" • "+(v.published||"")+(review?" • "+(v.handle||slug):"")+"</div>"+stLabel(v)
+(review?'<br><button class="pubbtn" onclick="askPub(\''+slug+"','"+v.id+"','"+v.title.replace(/'/g,"").substring(0,60)+'\',this)">Publish</button>':"")+"</div></div>";}
function renderPending(){let d=(STATE&&STATE.pending)||[];
let n=d.filter(x=>!x.error).length;
document.getElementById("pendCount").textContent=n?n+" video menunggu review":"Tidak ada video menunggu review 🎉";
let b=document.getElementById("pendBadge");b.textContent=n;b.classList.toggle("hidden",!n);
document.getElementById("pendList").innerHTML=d.length?d.map(v=>v.error?"":vrow(v,v.slug,true)).join(""):'<div class="empty">Semua video sudah tayang 🎉</div>';}
let pubTarget=null;
function askPub(slug,id,title,btn){pubTarget={slug:slug,id:id,btn:btn};document.getElementById("confirmText").textContent='Publish video ini ke publik? "'+title+'…"';document.getElementById("confirm").style.display="flex";}
document.getElementById("confirmNo").onclick=()=>{document.getElementById("confirm").style.display="none";};
document.getElementById("confirmYes").onclick=async()=>{document.getElementById("confirm").style.display="none";
let t=pubTarget;if(!t)return;t.btn.disabled=true;t.btn.textContent="…";
let cid="c"+Date.now().toString(36)+Math.floor(Math.random()*999);
try{await fb("commands/"+cid,"PUT",{slug:t.slug,videoId:t.id,title:"",ts:Date.now(),status:"pending"});
let tries=0,res=null;while(tries<40){await new Promise(r=>setTimeout(r,3000));tries++;
try{res=await fb("results/"+cid,"GET");if(res&&res.ts)break;}catch(e){}}
if(res&&res.ok){t.btn.textContent="✓ Tayang";loadState();}
else{t.btn.disabled=false;t.btn.textContent="Publish";alert("Gagal: "+((res&&res.error)||"timeout"));}}
catch(e){t.btn.disabled=false;t.btn.textContent="Publish";}};
async function loadState(){try{let s=await fb("state","GET");STATE=s||{};
document.getElementById("updAt").textContent="↻ "+(STATE.updated_at||"");
renderChannels();renderPending();renderRevenue();
}catch(e){document.getElementById("chGrid").innerHTML='<div class="empty" style="grid-column:1/-1">Gagal memuat. Periksa koneksi.</div>';}}
setInterval(()=>{try{if(localStorage.getItem("ytd")==="1")loadState();}catch(e){}},60000);
//]]>
</script>
</body>
</html>
